<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>BMANNY Payment Acknowledgment</title><style>
body{font-family:Arial,sans-serif;background:#f4f7fb;color:#12203a;margin:0;padding:32px}.receipt{max-width:680px;margin:auto;background:#fff;border:1px solid #d9e2f0;border-radius:12px;padding:34px}.top{display:flex;justify-content:space-between;border-bottom:3px solid #2196f3;padding-bottom:18px}.brand{font-size:24px;font-weight:800;color:#12366e}.muted{color:#61728d;font-size:13px}.title{font-size:22px;font-weight:800;margin:26px 0 8px}.amount{font-size:34px;font-weight:800;color:#2196f3;margin:12px 0 26px}.row{display:flex;justify-content:space-between;border-top:1px solid #e5ebf3;padding:13px 0;gap:20px}.label{color:#61728d}.value{text-align:right;font-weight:700}.notice{margin-top:24px;padding:14px;background:#edf7ff;border-radius:8px;color:#26517c;font-size:13px}@media print{body{background:#fff;padding:0}.receipt{border:0;max-width:none}.no-print{display:none}}</style></head><body>
<main class="receipt"><div class="top"><div><div class="brand">BMANNY</div><div class="muted">Partners Inc.</div></div><div class="muted">Payment acknowledgment<br>Order #{{ $order->order_id }}</div></div>
<h1 class="title">{{ ucfirst($milestone) }} Payment Verified</h1><div class="muted">This acknowledges that BMANNY verified the customer’s submitted bank-transfer proof.</div><div class="amount">₱{{ number_format((float) $amount, 2) }}</div>
<div class="row"><span class="label">Customer</span><span class="value">{{ $order->client?->business_name ?? '—' }}</span></div><div class="row"><span class="label">Quotation</span><span class="value">#{{ $order->quotation_id }}</span></div><div class="row"><span class="label">Payment milestone</span><span class="value">{{ ucfirst($milestone) }} payment</span></div><div class="row"><span class="label">Payment method</span><span class="value">Bank transfer</span></div><div class="row"><span class="label">Verified on</span><span class="value">{{ $verifiedAt->timezone('Asia/Manila')->format('M d, Y h:i A') }}</span></div><div class="row"><span class="label">Balance remaining</span><span class="value">₱{{ number_format((float) ($milestone === 'initial' ? $order->balance_payment_amount : 0), 2) }}</span></div>
<div class="notice">This is a BMANNY payment acknowledgment, not a bank-issued transaction receipt.</div><button class="no-print" onclick="window.print()" style="margin-top:22px;padding:11px 18px;background:#2196f3;border:0;border-radius:7px;color:white;font-weight:bold">Print receipt</button></main></body></html>
